pragma solidity 0.8.23;

import "@openzeppelin/contracts/access/manager/AccessManaged.sol";
import "@openzeppelin/contracts/proxy/Clones.sol";
import "@openzeppelin/contracts/utils/Pausable.sol";

import "@openzeppelin/contracts/access/manager/IAccessManager.sol";

import {IPoolManager} from "../../interfaces/IPoolManager.sol";
import {IPool} from "../../interfaces/IPool.sol";

import {Registered} from "../registry/Registered.sol";

import {PoolParameters} from "../../libraries/Data.sol";
import {VaultLogic} from "../../libraries/logic/VaultLogic.sol";

contract PoolManager is IPoolManager, AccessManaged, Pausable, Registered {
    address internal poolImplementation;

    uint256 public version;

    uint64 internal constant ROLE_ID =
        uint64(uint256(keccak256("MINTER_ROLE")));

    constructor(
        address _authority,
        address _registry,
        address _poolImplementation
    ) AccessManaged(_authority) Registered(_registry) {
        _setImplementation(_poolImplementation);
    }

    function setImplementation(address _address) external restricted {
        _setImplementation(_address);
    }

    // External API

    // @inheritdoc IPoolManager
    function deployPool(
        PoolParameters calldata _parameters
    ) external restricted whenNotPaused {
        VaultLogic.checkThreshold(_parameters.vaultParameters);

        bytes32 id = _calculateId(version, _parameters.name);

        address pool = _deployPool(id, version, _parameters);

        IAccessManager(authority()).grantRole(ROLE_ID, pool, 0);

        REGISTRY.registerPool(id, pool, _parameters);
    }

    function pause() external restricted {
        return _pause();
    }

    function unpause() external restricted {
        return _unpause();
    }

    // Internal API

    function _calculateId(
        uint256 _version,
        string calldata _name
    ) internal view returns (bytes32) {
        return keccak256(abi.encode(address(this), _version, _name));
    }

    function _deployPool(
        bytes32 _id,
        uint256 _version,
        PoolParameters calldata _parameters
    ) internal returns (address) {
        address clone = Clones.clone(poolImplementation);

        IPool(clone).initialize(REGISTRY_ADDRESS, _version, _id, _parameters);

        return clone;
    }

    function _setImplementation(address _address) internal {
        require(_address != address(0), "Address zero given.");

        poolImplementation = _address;
        version++;
    }
}
